window.SITE_DATA = [{"id": "algorithms", "title": "Algorithms", "icon": "🧠", "colour": "green", "desc": "Trace, debug, compare and refine algorithms using more demanding GCSE-style scenarios.", "subs": [{"id": "computational-thinking", "title": "Decomposition & Abstraction", "spec": "Topic 1", "learn": ["Decomposition breaks a complex problem into smaller sub-problems.", "Abstraction keeps the information needed for the problem and removes irrelevant detail.", "At Year 10 you should be able to apply both techniques to unfamiliar systems and justify why they make a solution easier to design."], "example": "For a parcel-delivery system, decompose the problem into customer details, parcel details, route planning, payment and tracking. Abstract away irrelevant details such as the driver's favourite music.", "tasks": [{"t": "mcq", "q": "A school is designing an online parents' evening system. Which action is decomposition?", "o": ["Removing the colour of the school logo", "Splitting the system into booking, login, teacher availability and confirmation", "Testing the final system", "Changing all variable names"], "a": 1, "why": "Decomposition breaks the whole system into smaller solvable parts."}, {"t": "classify", "q": "For a route-planning app, classify each detail.", "cats": ["Keep", "Abstract away"], "items": [["Road closures", 0], ["Current traffic", 0], ["Driver's favourite TV show", 1], ["Destination postcode", 0], ["Colour of nearby houses", 1]]}, {"t": "short", "q": "Explain why abstraction can reduce complexity in a program.", "keys": ["irrelevant", "detail"], "hint": "Mention removing details that do not affect the problem."}, {"t": "mcq", "q": "Which pair is correct?", "o": ["Decomposition = remove detail; abstraction = split problem", "Decomposition = split problem; abstraction = remove irrelevant detail", "Both mean testing", "Both mean repetition"], "a": 1, "why": "The two techniques solve different parts of managing complexity."}, {"t": "boss", "q": "A theme park wants an app for tickets, queues, maps, food ordering and ride photos. Decompose the system and explain what information you would abstract away in at least two parts."}]}, {"id": "trace-debug", "title": "Trace Tables & Debugging", "spec": "Topic 1", "learn": ["A trace table records how variables change as an algorithm runs.", "Tracing line by line is a reliable way to find logic errors.", "Year 10 questions may include nested selection, loops and values that change several times."], "example": "If total starts at 0 and a loop adds 2, then 4, then 6, the trace should record 0 → 2 → 6 → 12.", "tasks": [{"t": "trace", "q": "Trace the values after each line.", "code": "x = 3\ny = 2\nx = x + y\ny = x * 2\nprint(y)", "fields": [["x after line 3", "5"], ["y after line 4", "10"], ["output", "10"]]}, {"t": "mcq", "q": "A program runs but produces the wrong answer. What type of error is most likely?", "o": ["Syntax error", "Logic error", "Hardware error", "Authentication error"], "a": 1, "why": "Logic errors allow execution but produce an incorrect result."}, {"t": "trace", "q": "Trace this loop.", "code": "total = 1\nfor i in range(1,4):\n    total = total * i\nprint(total)", "fields": [["total after i=1", "1"], ["total after i=2", "2"], ["total after i=3", "6"], ["output", "6"]]}, {"t": "short", "q": "Why is a trace table useful when debugging?", "keys": ["variable", "change"], "hint": "Refer to seeing how variable values change line by line."}, {"t": "boss", "q": "A program should add the numbers 1 to 5 but outputs 10 instead of 15. Describe a systematic tracing method you would use to locate the logic error."}]}, {"id": "searching", "title": "Linear & Binary Search", "spec": "Topic 1", "learn": ["Linear search checks items one by one until the target is found or the list ends.", "Binary search repeatedly halves the search area.", "Binary search requires the data to be ordered before it can be used correctly.", "You should be able to choose an appropriate search and justify the choice."], "example": "Searching 3, 8, 11, 15, 20, 24, 31 for 20 using binary search: check 15, then search the upper half, then check 24 or 20 depending on the midpoint convention.", "tasks": [{"t": "searchsim", "mode": "linear", "q": "Carry out a linear search for 31. Drag the search marker across the values in the exact order a linear search would inspect them.", "values": [12, 7, 19, 4, 31, 8, 25], "target": 31}, {"t": "searchsim", "mode": "binary", "q": "Carry out a binary search for 31. Drag the search marker onto the values in the order they should be checked.", "values": [4, 9, 14, 20, 31, 44, 58], "target": 31}, {"t": "mcq", "q": "Why is binary search usually faster on a large ordered list?", "o": ["It checks every item twice", "It discards roughly half the remaining items each step", "It uses more memory", "It changes the data"], "a": 1, "why": "Halving the search space dramatically reduces comparisons."}, {"t": "short", "q": "State one condition required before binary search can be used correctly.", "keys": ["order"], "hint": "The list must be sorted/ordered."}, {"t": "boss", "q": "A school database has 50,000 student IDs stored in ascending order. Compare linear and binary search for finding one ID and recommend the better algorithm."}]}, {"id": "sorting", "title": "Bubble Sort & Merge Sort", "spec": "Topic 1", "learn": ["Bubble sort repeatedly compares adjacent items and swaps them when they are in the wrong order.", "Merge sort splits data into smaller lists, sorts them, then merges the ordered lists.", "You should be able to follow both algorithms and compare their behaviour."], "example": "Bubble sort on 5, 2, 4 starts by comparing 5 and 2 → 2, 5, 4, then 5 and 4 → 2, 4, 5.", "tasks": [{"t": "sortsim", "mode": "bubble", "q": "Bubble-sort the numbers into ascending order by dragging adjacent values past each other. Try to reach the sorted list using valid bubble-sort style swaps.", "values": [8, 3, 6, 1], "a": [1, 3, 6, 8]}, {"t": "sortsim", "mode": "merge", "q": "Merge the two already-sorted lists by dragging values into the output row in the correct order.", "left": [2, 7, 11], "right": [3, 5, 12], "a": [2, 3, 5, 7, 11, 12]}, {"t": "mcq", "q": "During bubble sort, what happens to the largest unsorted value after a complete pass?", "o": ["It usually moves toward the end", "It is deleted", "It moves to the start", "Nothing predictable"], "a": 0, "why": "Repeated adjacent swaps 'bubble' large values toward the end."}, {"t": "short", "q": "Give one reason merge sort may be preferred for larger datasets.", "keys": ["efficient"], "hint": "Think about how its growth compares with repeatedly scanning the whole list."}, {"t": "boss", "q": "Sort 8, 3, 6, 1 using bubble sort. Show each swap, then explain how merge sort would approach the same data differently."}]}, {"id": "algorithm-efficiency", "title": "Fitness & Efficiency", "spec": "Topic 1", "learn": ["An algorithm must be fit for purpose: it should solve the required problem correctly.", "Efficiency can be discussed using comparisons, loop passes and memory requirements.", "A faster algorithm may use more memory, so evaluation often involves trade-offs."], "example": "For a large ordered list, binary search usually needs far fewer comparisons than linear search, so it is more efficient for repeated lookups.", "tasks": [{"t": "mcq", "q": "Which measure can be used to compare algorithm efficiency at GCSE level?", "o": ["Number of comparisons", "Colour of the IDE", "Variable font", "Keyboard type"], "a": 0, "why": "Comparisons and loop passes are useful practical measures."}, {"t": "classify", "q": "Classify the consideration.", "cats": ["Fitness for purpose", "Efficiency"], "items": [["Produces the correct result", 0], ["Uses fewer comparisons", 1], ["Meets the user's requirement", 0], ["Needs fewer loop passes", 1]]}, {"t": "short", "q": "Why might the algorithm with the fewest steps not always be the best choice?", "keys": ["memory"], "hint": "Mention trade-offs such as memory, readability or suitability."}, {"t": "mcq", "q": "A search algorithm returns results quickly but sometimes returns the wrong item. Is it fit for purpose?", "o": ["Yes, because it is fast", "No, because correctness is essential", "Yes, if memory use is low", "Always"], "a": 1, "why": "An efficient wrong answer is still not fit for purpose."}, {"t": "boss", "q": "Two algorithms solve the same problem. Algorithm A uses fewer comparisons but much more memory. Algorithm B uses more comparisons but little memory. Explain how you would decide which is better for a small embedded device."}]}]}, {"id": "programming", "title": "Programming", "icon": "</>", "colour": "amber", "desc": "Apply Python constructs independently through tracing, debugging and problem solving.", "subs": [{"id": "data-types", "title": "Variables, Constants & Data Types", "spec": "Topic 6", "learn": ["Variables store values that can change; constants represent values intended to stay fixed.", "Primitive data types include integer, real, Boolean and character; strings are structured text data.", "Choosing an appropriate type improves correctness and clarity."], "example": "age = 15 uses an integer; temperature = 18.5 uses a real; loggedIn = True uses a Boolean.", "tasks": [{"t": "classify", "q": "Choose the most suitable type.", "cats": ["Integer", "Real", "Boolean", "String"], "items": [["Number of lives", 0], ["Average temperature", 1], ["Has permission?", 2], ["Full name", 3]]}, {"t": "mcq", "q": "Which value is most suitable as a constant?", "o": ["currentScore", "MAX_LIVES = 3", "playerName", "currentLevel"], "a": 1, "why": "The maximum number of lives is designed not to change."}, {"t": "short", "q": "Why is score a better variable name than s in a larger program?", "keys": ["read", "understand"], "hint": "Refer to readability/maintenance."}, {"t": "trace", "q": "Predict the final values.", "code": "age = 14\nnextAge = age + 1\nage = nextAge + 1", "fields": [["nextAge", "15"], ["age", "16"]]}, {"t": "boss", "q": "Plan the data for a simple fitness-tracking program. Identify suitable variables, one constant and appropriate data types, justifying at least three choices."}]}, {"id": "selection-logic", "title": "Selection & Boolean Logic", "spec": "Topic 6", "learn": ["Selection uses conditions to choose between different paths.", "Conditions use relational operators such as >, <, >=, <=, = and !=.", "AND, OR and NOT can combine or invert Boolean conditions.", "Nested selection can handle more than two outcomes."], "example": "if age >= 16 and hasConsent: print('Allowed') requires both conditions to be true.", "tasks": [{"t": "mcq", "q": "Which condition is true only when both requirements are met?", "o": ["A OR B", "A AND B", "NOT A", "A != B"], "a": 1, "why": "AND requires both inputs to be true."}, {"t": "trace", "q": "Predict the output.", "code": "score = 72\nif score >= 80:\n    print('A')\nelif score >= 60:\n    print('B')\nelse:\n    print('C')", "fields": [["output", "B"]]}, {"t": "classify", "q": "Choose the most suitable operator.", "cats": ["AND", "OR", "NOT"], "items": [["Both username and password correct", 0], ["Weekend or bank holiday", 1], ["User is not blocked", 2]]}, {"t": "short", "q": "Why might elif be better than several separate if statements when only one outcome should happen?", "keys": ["one"], "hint": "Explain that only one branch should be selected."}, {"t": "boss", "q": "Write or describe selection for a theme-park ride: riders must be at least 140 cm tall AND at least 12 years old, unless accompanied by an adult. Explain your Boolean logic."}]}, {"id": "loops", "title": "FOR, WHILE & Iteration", "spec": "Topic 6", "learn": ["FOR loops are used when the number of repetitions is known or when iterating through a structure.", "WHILE loops repeat while a condition remains true.", "Loop conditions and updates must be designed carefully to avoid infinite loops.", "Nested loops can repeat a repeated process."], "example": "for name in names: print(name) iterates once over every item in names.", "tasks": [{"t": "classify", "q": "Choose the best loop type.", "cats": ["FOR", "WHILE"], "items": [["Print every name in a list", 0], ["Keep asking until password is correct", 1], ["Repeat exactly 10 times", 0], ["Run while lives > 0", 1]]}, {"t": "trace", "q": "Trace the loop.", "code": "total = 0\nfor i in range(1,5):\n    total = total + i\nprint(total)", "fields": [["output", "10"]]}, {"t": "mcq", "q": "What causes many infinite loops?", "o": ["The condition never becomes false", "Using print", "Using a variable", "Having an input"], "a": 0, "why": "A WHILE loop needs something that eventually changes the condition."}, {"t": "short", "q": "Explain the difference between count-controlled and condition-controlled repetition.", "keys": ["count", "condition"], "hint": "Mention known number of repeats versus repeating while/until a condition."}, {"t": "boss", "q": "Design a loop-based program that repeatedly asks for a mark from 0–100 until a valid value is entered, then prints it. Explain why your loop terminates."}]}, {"id": "strings-arrays", "title": "Strings, Arrays & Lists", "spec": "Topic 6", "learn": ["Strings are sequences of characters and individual positions can be accessed using an index.", "Arrays/lists store multiple related values under one name.", "Iteration is commonly used to process every item in a list.", "String operations include length, position, substring and case conversion."], "example": "word = 'COMPUTER'; word[0] is 'C' and len(word) is 8.", "tasks": [{"t": "number", "q": "What is the length of the string 'NETWORK'?", "answer": "7", "hint": "Count every character."}, {"t": "mcq", "q": "In Python, what is the index of the first character in a string?", "o": ["1", "0", "-1", "It has no index"], "a": 1, "why": "Python indexing starts at 0."}, {"t": "trace", "q": "Predict the output.", "code": "word = 'Python'\nprint(word[1])\nprint(word.upper())", "fields": [["first output", "y"], ["second output", "PYTHON"]]}, {"t": "short", "q": "Why is a list better than five separate variables for five test scores?", "keys": ["related", "loop"], "hint": "Mention storing related data together and easier iteration."}, {"t": "boss", "q": "A program stores 30 temperatures in a list. Describe how you would find the total, average, highest value and number of temperatures above 25."}]}, {"id": "subprograms", "title": "Subprograms & Parameters", "spec": "Topic 6", "learn": ["A subprogram performs a specific named task.", "Parameters pass information into a subprogram.", "Functions can return a value to the calling code.", "Subprograms reduce duplication and support testing, maintenance and decomposition."], "example": "def area(width, height): return width * height uses two parameters and returns a result.", "tasks": [{"t": "mcq", "q": "What is a parameter?", "o": ["A syntax error", "A value/name used to pass data into a subprogram", "A storage device", "A network layer"], "a": 1, "why": "Parameters let the calling code provide data to the subprogram."}, {"t": "trace", "q": "Predict the output.", "code": "def double(n):\n    return n * 2\nx = double(7)\nprint(x)", "fields": [["output", "14"]]}, {"t": "classify", "q": "Classify the benefit.", "cats": ["Readability", "Reuse", "Testing"], "items": [["One clear named task", 0], ["Call the same code many times", 1], ["Check one component separately", 2]]}, {"t": "short", "q": "Explain the difference between printing a value and returning a value from a function.", "keys": ["return", "use"], "hint": "A returned value can be stored or used by the calling code."}, {"t": "boss", "q": "Design subprograms for a quiz program that asks questions, checks answers, updates the score and prints a result. Include at least one parameter and one returned value."}]}, {"id": "files-debugging", "title": "File Handling & Debugging", "spec": "Topic 6", "learn": ["Programs can read data from and write data to files, including CSV files.", "Syntax errors break programming-language rules; logic errors produce an incorrect result; runtime errors occur while the program is running.", "Testing should include normal, boundary and erroneous/invalid data where relevant."], "example": "A CSV might store name,score on each row. A program can read each row, split fields and process the values.", "tasks": [{"t": "classify", "q": "Classify the error.", "cats": ["Syntax", "Logic", "Runtime"], "items": [["Missing colon after if", 0], ["Average calculation divides by the wrong value", 1], ["Program tries to open a missing file", 2]]}, {"t": "mcq", "q": "What is a CSV file mainly useful for?", "o": ["Storing structured text data in rows/fields", "Running Python instructions", "Encrypting passwords automatically", "Replacing RAM"], "a": 0, "why": "CSV is a simple text format for tabular data."}, {"t": "short", "q": "Why should a program close a file after use?", "keys": ["resource"], "hint": "Mention releasing the file/resource or ensuring writes complete."}, {"t": "mcq", "q": "Which test value checks the exact edge of an allowed range 1–100?", "o": ["50", "100", "hello", "-999"], "a": 1, "why": "Boundary tests target values at the edge of valid ranges."}, {"t": "boss", "q": "A program reads student scores from a CSV file and calculates an average. Describe a sensible test plan and at least three errors or unusual cases the programmer should consider."}]}]}, {"id": "data", "title": "Data", "icon": "💾", "colour": "blue", "desc": "Represent numbers, text, images and sound, then calculate storage and evaluate compression.", "subs": [{"id": "signed-binary", "title": "Unsigned & Two's Complement", "spec": "Topic 2", "learn": ["Unsigned binary represents zero and positive integers.", "Two's complement allows an 8-bit value to represent -128 to +127.", "The most significant bit has a negative place value in two's complement.", "You should distinguish signed and unsigned ranges."], "example": "8-bit unsigned 11111111 = 255. In 8-bit two's complement, the same bit pattern represents -1.", "tasks": [{"t": "mcq", "q": "What is the largest unsigned 8-bit value?", "o": ["127", "128", "255", "256"], "a": 2, "why": "Eight bits give values 0–255 when unsigned."}, {"t": "mcq", "q": "What range can 8-bit two's complement represent?", "o": ["0 to 255", "-127 to 127", "-128 to 127", "-255 to 255"], "a": 2, "why": "Two's complement uses -128 as the negative extreme and +127 as the positive extreme."}, {"t": "number", "q": "Convert unsigned binary 10110110 to denary.", "answer": "182", "hint": "Use 128 + 32 + 16 + 4 + 2."}, {"t": "short", "q": "Why can the same 8-bit pattern represent different values depending on whether it is signed or unsigned?", "keys": ["interpret"], "hint": "The bits are interpreted using different place-value rules."}, {"t": "boss", "q": "Explain how 11111101 is interpreted as an 8-bit two's-complement number and why it is not 253 in that context."}]}, {"id": "binary-arithmetic", "title": "Binary Addition & Overflow", "spec": "Topic 2", "learn": ["Binary addition follows the same carry principle as denary addition.", "In a fixed number of bits, a result may be too large to represent.", "Overflow occurs when the result is outside the representable range."], "example": "11110000 + 00100000 = 1 00010000. In an 8-bit register the extra carry shows overflow for unsigned arithmetic.", "tasks": [{"t": "number", "q": "Add 00001101 and 00000111. Give the 8-bit result.", "answer": "00010100", "hint": "13 + 7 = 20, then convert 20 to 8-bit binary."}, {"t": "mcq", "q": "What does overflow mean?", "o": ["The CPU gets wet", "A result cannot be represented using the available number of bits", "A file is compressed", "A network is too slow"], "a": 1, "why": "Overflow is a representational limit."}, {"t": "number", "q": "What is 11111111 + 00000001 in denary before limiting it to 8 bits?", "answer": "256", "hint": "255 + 1 = 256."}, {"t": "short", "q": "Why is overflow a problem in fixed-width binary arithmetic?", "keys": ["wrong", "result"], "hint": "The stored value may wrap/lose information and no longer match the true result."}, {"t": "boss", "q": "An 8-bit unsigned sensor counter currently stores 250 and adds 12. Explain what should happen mathematically and why an 8-bit system cannot represent the result correctly."}]}, {"id": "binary-shifts", "title": "Logical & Arithmetic Shifts", "spec": "Topic 2", "learn": ["A logical left shift moves bits left and fills new positions with 0.", "For unsigned values, a logical left shift by one usually multiplies by 2 if no significant bit is lost.", "A logical right shift usually divides an unsigned value by 2 using integer behaviour.", "Arithmetic right shifts preserve the sign bit for signed values."], "example": "00001101 shifted logically left by 1 becomes 00011010: 13 becomes 26.", "tasks": [{"t": "number", "q": "What denary value results from logically shifting 00000101 left by 2?", "answer": "20", "hint": "5 × 4 = 20 if no bits are lost."}, {"t": "mcq", "q": "Which shift preserves the sign bit of a signed value when shifting right?", "o": ["Logical right", "Arithmetic right", "Logical left", "No shift"], "a": 1, "why": "Arithmetic right shift copies/preserves the sign bit."}, {"t": "number", "q": "Logically shift 00110000 right by 2. Give the 8-bit result.", "answer": "00001100", "hint": "Move every bit two places right and insert zeros on the left."}, {"t": "short", "q": "Why can a left shift cause data loss?", "keys": ["bit", "lost"], "hint": "A 1 shifted beyond the fixed bit width is discarded."}, {"t": "boss", "q": "Compare logical and arithmetic right shifts. Explain why using the wrong type on a negative two's-complement value can change its meaning."}]}, {"id": "hexadecimal", "title": "Hexadecimal", "spec": "Topic 2", "learn": ["Hexadecimal is a compact representation of binary.", "One hexadecimal digit represents exactly four binary bits.", "Hex digits run 0–9 then A–F.", "Converting through 4-bit groups is usually faster and less error-prone than converting via denary."], "example": "Binary 1101 1010 = hexadecimal DA.", "tasks": [{"t": "mcq", "q": "How many bits does one hexadecimal digit represent?", "o": ["2", "4", "8", "16"], "a": 1, "why": "One hex digit maps to one 4-bit nibble."}, {"t": "number", "q": "Convert binary 10101111 to hexadecimal.", "answer": "AF", "hint": "Split into 1010 (A) and 1111 (F)."}, {"t": "number", "q": "Convert hexadecimal 3C to 8-bit binary.", "answer": "00111100", "hint": "3 = 0011 and C = 1100."}, {"t": "short", "q": "Give one reason hexadecimal is used instead of long binary strings.", "keys": ["short"], "hint": "It is shorter/easier for humans to read and transcribe."}, {"t": "boss", "q": "Convert 1110 0101 1011 0010 to hexadecimal, then explain why grouping into nibbles is reliable."}]}, {"id": "text-representation", "title": "Characters & ASCII", "spec": "Topic 2", "learn": ["Character sets assign numeric codes to characters.", "ASCII is a character-encoding standard used to represent text.", "More characters require a larger character set and potentially more bits per character.", "Text files are ultimately stored as binary codes representing characters."], "example": "The character 'A' has an ASCII code; the code is stored in binary rather than storing a literal letter inside memory.", "tasks": [{"t": "mcq", "q": "What does a character set provide?", "o": ["A numeric code for each supported character", "A faster CPU", "A type of router", "An image resolution"], "a": 0, "why": "Character sets map characters to numeric codes."}, {"t": "mcq", "q": "Why are character encodings needed?", "o": ["Computers store binary, not abstract letters directly", "Screens only use hex", "Networks cannot carry text", "RAM only stores images"], "a": 0, "why": "Text must be represented using numeric/binary codes."}, {"t": "short", "q": "Why might a larger character set require more bits per character?", "keys": ["more", "characters"], "hint": "More possible symbols require more unique binary codes."}, {"t": "classify", "q": "Which data is text?", "cats": ["Text/character data", "Not primarily text"], "items": [["Student surname", 0], ["A JPEG photo", 1], ["Email subject", 0], ["Recorded speech waveform", 1]]}, {"t": "boss", "q": "Explain how the word CAT can be stored in a computer using a character set, from characters to codes to binary."}]}, {"id": "images", "title": "Image Representation", "spec": "Topic 2", "learn": ["Bitmap images are made from pixels arranged in a grid.", "Resolution is the number of pixels, commonly width × height.", "Colour depth is the number of bits used to represent each pixel's colour.", "Approximate uncompressed file size = width × height × colour depth."], "example": "800 × 600 image at 24-bit colour depth: 800 × 600 × 24 bits before converting to bytes.", "tasks": [{"t": "number", "q": "How many pixels are in a 1920 × 1080 image?", "answer": "2073600", "hint": "Multiply width by height."}, {"t": "mcq", "q": "Increasing colour depth mainly increases what?", "o": ["Number of possible colours and file size", "CPU clock speed", "Network range", "Number of files"], "a": 0, "why": "More bits per pixel allow more colours but require more storage."}, {"t": "number", "q": "Calculate the uncompressed size in bits of a 100 × 50 image using 8-bit colour depth.", "answer": "40000", "hint": "100 × 50 × 8."}, {"t": "short", "q": "Why can increasing resolution improve image detail?", "keys": ["pixel"], "hint": "More pixels can represent finer detail."}, {"t": "boss", "q": "A 1280 × 720 image uses 24-bit colour. Calculate its uncompressed size in bits and bytes, then explain two ways changing image settings would alter file size."}]}, {"id": "sound", "title": "Sound Representation", "spec": "Topic 2", "learn": ["Digital sound is created by sampling an analogue waveform.", "Sample rate is how many samples are taken each second.", "Sample resolution/bit depth is how many bits are used per sample.", "Approximate uncompressed sound size = sample rate × bit depth × duration × channels."], "example": "44,100 samples/s × 16 bits × 10 seconds gives the number of bits for 10 seconds of mono sound.", "tasks": [{"t": "mcq", "q": "What does sample rate measure?", "o": ["Samples taken per second", "Bits per pixel", "CPU instructions per second", "Packets per router"], "a": 0, "why": "Sample rate is the number of waveform measurements each second."}, {"t": "mcq", "q": "Increasing sample resolution mainly allows what?", "o": ["More precise amplitude values", "More pixels", "More network addresses", "More loops"], "a": 0, "why": "More bits per sample allow more possible amplitude levels."}, {"t": "number", "q": "A mono clip uses 8,000 samples/s, 8 bits/sample for 2 seconds. Size in bits?", "answer": "128000", "hint": "8000 × 8 × 2."}, {"t": "short", "q": "Why do higher sample rate and higher bit depth usually increase quality and file size?", "keys": ["more", "data"], "hint": "More measurements and/or more detail per measurement are stored."}, {"t": "boss", "q": "Compare two audio settings for a voice recording: 8 kHz/8-bit and 44.1 kHz/16-bit. Explain the likely difference in quality and storage."}]}, {"id": "compression", "title": "Compression", "spec": "Topic 2", "learn": ["Compression reduces file size.", "Lossless compression allows the original data to be reconstructed exactly.", "Lossy compression permanently removes some data to achieve greater size reduction.", "The best choice depends on the file type and how much quality loss is acceptable."], "example": "A PNG image commonly uses lossless compression; a JPEG image often uses lossy compression.", "tasks": [{"t": "classify", "q": "Classify the use.", "cats": ["Lossless preferred", "Lossy may be suitable"], "items": [["Program source code", 0], ["Holiday photo for a website", 1], ["Legal document text", 0], ["Streaming music", 1]]}, {"t": "mcq", "q": "What is the key property of lossless compression?", "o": ["The original can be reconstructed exactly", "It always halves the file", "It destroys metadata only", "It cannot compress images"], "a": 0, "why": "No information needed to reconstruct the original is permanently lost."}, {"t": "short", "q": "Why might a streaming service choose lossy compression?", "keys": ["smaller"], "hint": "Smaller files reduce bandwidth/storage while acceptable quality is retained."}, {"t": "mcq", "q": "Which factor matters when choosing compression?", "o": ["Required quality", "Acceptable file size", "Type of data", "All of these"], "a": 3, "why": "Compression choice depends on quality, size and the purpose/type of data."}, {"t": "boss", "q": "A school needs to store exam papers, student photos and recorded assemblies. Recommend suitable compression approaches for each and justify your choices."}]}]}, {"id": "computers", "title": "Computers", "icon": "🖥️", "colour": "emerald", "desc": "Understand CPU architecture, the FDE cycle, memory, storage, performance and embedded systems.", "subs": [{"id": "von-neumann", "title": "Von Neumann Architecture", "spec": "Topic 3", "learn": ["In a Von Neumann system, instructions and data are stored in memory.", "The CPU fetches instructions from memory, decodes them and executes them.", "The CPU communicates with memory and devices using buses."], "example": "A stored program is held in memory alongside the data it processes; the CPU repeatedly follows the fetch–decode–execute cycle.", "tasks": [{"t": "mcq", "q": "What is a key idea of Von Neumann architecture?", "o": ["Instructions and data can both be stored in memory", "Programs are only stored on paper", "The CPU has no memory connection", "Every instruction needs a separate CPU"], "a": 0, "why": "Stored-program architecture keeps instructions and data in memory."}, {"t": "classify", "q": "Classify each item.", "cats": ["CPU", "Memory", "Bus"], "items": [["ALU", 0], ["RAM", 1], ["Data bus", 2], ["Control Unit", 0]]}, {"t": "short", "q": "Why does the CPU need access to memory during program execution?", "keys": ["instruction", "data"], "hint": "It must fetch instructions and read/write data."}, {"t": "mcq", "q": "Which sequence best summarises CPU operation?", "o": ["Store-delete-print", "Fetch-decode-execute", "Input-output-erase", "Search-sort-merge"], "a": 1, "why": "FDE is the repeated instruction-processing cycle."}, {"t": "boss", "q": "Explain how CPU, memory and buses work together in a stored-program computer when a program is running."}]}, {"id": "cpu-components", "title": "CPU Components", "spec": "Topic 3", "learn": ["The Control Unit coordinates CPU activity and sends control signals.", "The ALU performs arithmetic and logical operations.", "Registers are very small, very fast storage locations inside the CPU.", "The clock provides timing pulses that coordinate operations."], "example": "When executing an addition instruction, the CU coordinates the operation and the ALU performs the calculation, using registers for immediate values/results.", "tasks": [{"t": "classify", "q": "Match each role.", "cats": ["Control Unit", "ALU", "Registers", "Clock"], "items": [["Performs calculations", 1], ["Coordinates operations", 0], ["Very fast internal storage", 2], ["Provides timing pulses", 3]]}, {"t": "mcq", "q": "Which component performs comparisons such as greater than?", "o": ["ALU", "SSD", "Router", "RAM"], "a": 0, "why": "Logical comparisons are handled by the ALU."}, {"t": "short", "q": "Why are registers useful even though the computer already has RAM?", "keys": ["fast"], "hint": "Registers are much faster and are inside the CPU."}, {"t": "mcq", "q": "What does the CPU clock influence?", "o": ["Timing/rate of CPU operations", "Disk capacity", "Screen resolution", "IP address"], "a": 0, "why": "Clock pulses coordinate operations and clock rate is one performance factor."}, {"t": "boss", "q": "A student says 'the ALU controls the whole CPU and registers permanently store programs'. Identify both errors and correct the explanation."}]}, {"id": "buses", "title": "Address, Data & Control Buses", "spec": "Topic 3", "learn": ["The address bus carries the address of a memory location.", "The data bus carries data and instructions between components.", "The control bus carries control signals such as read/write instructions.", "The buses work together during memory access and the FDE cycle."], "example": "To read from RAM: the CPU places an address on the address bus, sends a read signal on the control bus, then data returns on the data bus.", "tasks": [{"t": "classify", "q": "Choose the correct bus.", "cats": ["Address", "Data", "Control"], "items": [["Carries a memory location", 0], ["Carries an instruction back to CPU", 1], ["Carries a read signal", 2], ["Carries a value being written to RAM", 1]]}, {"t": "order", "q": "Put a simplified RAM read into order.", "items": [["CPU specifies memory address", "a"], ["Read control signal is sent", "b"], ["RAM accesses the location", "c"], ["Data travels back to CPU", "d"]], "a": ["a", "b", "c", "d"]}, {"t": "mcq", "q": "Which bus is normally one-way from CPU to memory for location selection?", "o": ["Address bus", "Data bus", "Control bus always", "USB"], "a": 0, "why": "The address bus identifies where to access."}, {"t": "short", "q": "Explain why the data bus must be able to carry both instructions and ordinary data.", "keys": ["instruction", "data"], "hint": "Both are transferred between CPU and memory."}, {"t": "boss", "q": "Describe how all three buses are used when the CPU fetches an instruction from RAM."}]}, {"id": "fde", "title": "Fetch–Decode–Execute Cycle", "spec": "Topic 3", "learn": ["Fetch: the CPU obtains the next instruction from memory.", "Decode: the Control Unit works out what the instruction means.", "Execute: the appropriate CPU component carries out the instruction.", "The cycle repeats continuously while a program runs."], "example": "For an ADD instruction, the CPU fetches its binary instruction, decodes it as an addition operation, then the ALU executes the addition.", "tasks": [{"t": "order", "q": "Put the main FDE stages in order.", "items": [["Fetch", "f"], ["Decode", "d"], ["Execute", "e"]], "a": ["f", "d", "e"]}, {"t": "classify", "q": "Identify the stage.", "cats": ["Fetch", "Decode", "Execute"], "items": [["Instruction transferred from RAM", 0], ["CU interprets the instruction", 1], ["ALU carries out an addition", 2], ["Next instruction is obtained", 0]]}, {"t": "mcq", "q": "Which component has the main role in decoding instructions?", "o": ["Control Unit", "SSD", "Network card", "Monitor"], "a": 0, "why": "The Control Unit interprets/decodes the fetched instruction."}, {"t": "short", "q": "What is the purpose of the fetch stage?", "keys": ["instruction", "memory"], "hint": "The next instruction must be obtained from memory."}, {"t": "boss", "q": "A computer successfully fetches instructions but the Control Unit cannot interpret them. Explain where the FDE cycle fails and what effect this would have on program execution."}]}, {"id": "ram-storage", "title": "RAM & Secondary Storage", "spec": "Topic 3", "learn": ["RAM stores programs and data currently in use.", "RAM is volatile: its contents are lost when power is removed.", "Secondary storage is non-volatile and is used for long-term storage.", "Programs are typically copied from secondary storage into RAM before the CPU processes them."], "example": "A Python file may be stored on an SSD. When opened, the program and required data are loaded into RAM so the CPU can access them quickly.", "tasks": [{"t": "classify", "q": "Classify each property.", "cats": ["RAM", "Secondary storage"], "items": [["Volatile", 0], ["Long-term storage", 1], ["Holds currently running programs", 0], ["Retains data without power", 1]]}, {"t": "order", "q": "Put these steps in a sensible order when opening a saved application.", "items": [["Application stored on SSD", "a"], ["Application loaded into RAM", "b"], ["CPU fetches instructions from RAM", "c"], ["Program runs", "d"]], "a": ["a", "b", "c", "d"]}, {"t": "mcq", "q": "Why is an SSD not used as a direct replacement for CPU registers?", "o": ["It is much slower than registers", "It is volatile", "It cannot store files", "It only stores images"], "a": 0, "why": "Storage technologies have very different access speeds."}, {"t": "short", "q": "Why does a computer still need secondary storage if it has RAM?", "keys": ["power", "long"], "hint": "RAM is volatile; long-term data needs non-volatile storage."}, {"t": "boss", "q": "A student says 'when I double-click a game, the CPU executes it directly from the SSD'. Correct this explanation using secondary storage, RAM and CPU."}]}, {"id": "storage-tech", "title": "Storage Technologies", "spec": "Topic 3", "learn": ["Magnetic storage includes hard disk drives.", "Solid-state storage uses flash memory and has no moving parts.", "Optical storage uses laser-read media such as discs.", "Storage choices depend on capacity, speed, durability, portability and cost."], "example": "For a laptop that is carried daily, an SSD is often preferable because it is fast and has no moving parts, although cost per GB may be higher.", "tasks": [{"t": "classify", "q": "Classify the technology.", "cats": ["Magnetic", "Solid state", "Optical"], "items": [["HDD", 0], ["SSD", 1], ["USB flash drive", 1], ["Blu-ray disc", 2]]}, {"t": "mcq", "q": "Which is a common advantage of SSDs over HDDs?", "o": ["No moving parts", "Always cheaper per GB", "Unlimited writes", "Needs a laser"], "a": 0, "why": "No moving parts improves durability and often access speed."}, {"t": "mcq", "q": "Which factor is most important for a large backup archive where low cost per GB matters more than portability?", "o": ["Capacity/cost", "Screen size", "CPU clock only", "Colour depth"], "a": 0, "why": "Storage should be evaluated against the scenario."}, {"t": "short", "q": "Give one disadvantage of optical storage for everyday laptop use.", "keys": ["capacity"], "hint": "Capacity/speed/convenience are reasonable considerations."}, {"t": "boss", "q": "Recommend storage for: a gaming laptop, a CCTV archive, and distributing a small read-only software package. Justify each choice using at least two characteristics."}]}, {"id": "performance-embedded", "title": "CPU Performance & Embedded Systems", "spec": "Topic 3", "learn": ["CPU performance is influenced by factors such as clock speed, number of cores and cache.", "More cores can allow more work in parallel when software supports it.", "Cache stores frequently/recently used data close to the CPU.", "Embedded systems are computers built into larger devices to perform specific functions."], "example": "A washing machine controller is an embedded system: it monitors inputs, follows a program and controls outputs for a specific purpose.", "tasks": [{"t": "classify", "q": "Classify the factor.", "cats": ["CPU performance factor", "Not a CPU performance factor"], "items": [["Clock speed", 0], ["Number of cores", 0], ["Cache size", 0], ["Wallpaper colour", 1]]}, {"t": "mcq", "q": "Why can cache improve performance?", "o": ["It keeps frequently needed data/instructions close to the CPU", "It increases monitor size", "It replaces all storage", "It gives a public IP"], "a": 0, "why": "Cache reduces the need to wait for slower main memory."}, {"t": "mcq", "q": "Which is most likely an embedded system?", "o": ["Traffic-light controller", "General desktop PC", "Gaming laptop used for many tasks", "School server"], "a": 0, "why": "Embedded systems usually perform a dedicated function inside a larger system."}, {"t": "short", "q": "Why does doubling clock speed not necessarily double overall computer performance?", "keys": ["other"], "hint": "Other bottlenecks/factors such as cores, memory and software matter."}, {"t": "boss", "q": "A smart greenhouse uses sensors, a controller and outputs. Explain why it is an embedded system and identify how CPU performance, memory and reliability matter in this context."}]}]}, {"id": "networks", "title": "Networks", "icon": "🌐", "colour": "purple", "desc": "Explain how devices communicate, compare network designs and apply protocols and TCP/IP.", "subs": [{"id": "network-purpose", "title": "Why Networks? LAN & WAN", "spec": "Topic 4", "learn": ["Networks allow sharing of data, hardware, internet access and services.", "A LAN covers a limited geographical area; a WAN connects over a wider area.", "Network design should consider security, performance, cost and reliability."], "example": "A school site network is usually a LAN. A company connecting offices in several countries uses a WAN.", "tasks": [{"t": "classify", "q": "Classify each network.", "cats": ["LAN", "WAN"], "items": [["One school building", 0], ["Company offices across Europe", 1], ["Home Wi-Fi network", 0], ["Bank branches nationwide", 1]]}, {"t": "mcq", "q": "Which is a benefit of networking computers?", "o": ["Shared resources", "No security risks", "Infinite bandwidth", "No maintenance"], "a": 0, "why": "Networks can share files, printers, services and internet access."}, {"t": "short", "q": "Give one disadvantage or risk introduced by networking.", "keys": ["security"], "hint": "Security, dependence on network availability or management cost are valid."}, {"t": "mcq", "q": "Which factor could make a WAN more complex than a LAN?", "o": ["Larger geographic scale", "Fewer users always", "No routers", "No protocols"], "a": 0, "why": "Long-distance connections increase complexity and reliance on infrastructure."}, {"t": "boss", "q": "A school is opening a second campus five miles away. Explain how its networking requirements differ from connecting computers within one classroom."}]}, {"id": "internet-ip", "title": "Internet, IP Addresses & Routers", "spec": "Topic 4", "learn": ["The internet is a global network of interconnected networks.", "IP addresses identify devices/interfaces on networks.", "Routers forward packets between networks towards their destination.", "A route may involve several routers rather than one direct connection."], "example": "A packet leaving a home LAN is sent to a router, forwarded through other networks and routers, then delivered to the destination network.", "tasks": [{"t": "mcq", "q": "What is the main job of a router?", "o": ["Forward packets between networks", "Store all files permanently", "Perform arithmetic", "Display websites"], "a": 0, "why": "Routers make forwarding decisions between networks."}, {"t": "mcq", "q": "What is an IP address used for?", "o": ["Identifying a network interface/device for communication", "Increasing CPU speed", "Compressing files", "Drawing graphics"], "a": 0, "why": "IP addresses are used in network addressing/routing."}, {"t": "order", "q": "Put this simplified internet journey in order.", "items": [["Device creates data to send", "a"], ["Local router receives packet", "b"], ["Routers forward across networks", "c"], ["Destination network receives packet", "d"]], "a": ["a", "b", "c", "d"]}, {"t": "short", "q": "Why might a packet pass through several routers?", "keys": ["network"], "hint": "The internet is made of many interconnected networks."}, {"t": "boss", "q": "Explain what happens at a high level when a laptop in Jersey requests a webpage from a server in another country, using IP addresses and routers."}]}, {"id": "network-performance", "title": "Wired, Wireless & Performance", "spec": "Topic 4", "learn": ["Wired and wireless connections have different trade-offs.", "Bandwidth is the amount of data that can be transferred per unit time.", "Latency is delay before/while data is transferred.", "Range and interference are important when evaluating wireless networks."], "example": "A competitive gaming PC may benefit from Ethernet because low latency and stability matter more than mobility.", "tasks": [{"t": "classify", "q": "Choose the connection that is usually more suitable.", "cats": ["Ethernet", "Wi-Fi"], "items": [["Fixed desktop gaming PC", 0], ["Tablet used around a classroom", 1], ["Server rack", 0], ["Phone moving around a house", 1]]}, {"t": "mcq", "q": "What does latency describe?", "o": ["Delay", "Storage capacity", "Number of colours", "CPU cores"], "a": 0, "why": "Latency is time delay in communication."}, {"t": "mcq", "q": "What does greater bandwidth allow?", "o": ["More data to be transferred per unit time", "A stronger password", "A bigger SSD", "A faster ALU automatically"], "a": 0, "why": "Bandwidth is data-transfer capacity."}, {"t": "short", "q": "Why can Wi-Fi performance fall as a device moves farther from the access point?", "keys": ["signal"], "hint": "Signal strength/range and interference affect performance."}, {"t": "boss", "q": "Recommend wired or wireless networking for a school esports room, student tablets and an outdoor event. Justify each using bandwidth, latency, range and mobility."}]}, {"id": "topologies", "title": "Network Topologies", "spec": "Topic 4", "learn": ["A topology describes how network devices are connected.", "Star topology connects devices to a central switch/device.", "Topology affects reliability, cabling and the impact of component failure.", "You should evaluate a topology for a scenario rather than memorise one 'best' answer."], "example": "In a star network, failure of one end-device cable normally affects that device only, but failure of the central device can affect the whole network.", "tasks": [{"t": "mcq", "q": "What is a key feature of a star topology?", "o": ["Devices connect via a central device", "Every device connects in one closed ring only", "No cables are needed", "All data is stored centrally"], "a": 0, "why": "The central connection point defines a star topology."}, {"t": "classify", "q": "Classify the statement.", "cats": ["Star advantage", "Star disadvantage"], "items": [["One cable failure usually affects one device", 0], ["Central device failure can affect all devices", 1], ["Easy to add devices", 0], ["Requires central hardware", 1]]}, {"t": "short", "q": "Why can a star topology be easier to troubleshoot?", "keys": ["device"], "hint": "Faults can often be isolated to a particular device/cable."}, {"t": "mcq", "q": "A central switch fails in a star network. What is the likely effect?", "o": ["Many/all connected devices lose network connectivity", "Only one mouse stops", "Nothing changes", "The internet becomes faster"], "a": 0, "why": "The central device is a key dependency."}, {"t": "boss", "q": "A small office is choosing a topology for 25 computers. Evaluate star topology for reliability, maintenance and cost."}]}, {"id": "protocols", "title": "Network Protocols", "spec": "Topic 4", "learn": ["Protocols are agreed rules for communication.", "HTTP/HTTPS are used for web communication; HTTPS adds encryption/authentication protections.", "FTP is used for transferring files.", "SMTP is used to send email; POP3 and IMAP are used to retrieve/manage email in different ways."], "example": "A web browser requesting a secure login page typically uses HTTPS rather than plain HTTP.", "tasks": [{"t": "classify", "q": "Choose the protocol.", "cats": ["HTTP/HTTPS", "FTP", "SMTP", "IMAP/POP3"], "items": [["Send an email", 2], ["Transfer website files to a server", 1], ["Access a secure website", 0], ["Retrieve email from a mail server", 3]]}, {"t": "mcq", "q": "Why is HTTPS preferred for sensitive web data?", "o": ["It provides encrypted secure communication", "It always makes the CPU faster", "It removes passwords", "It is a storage format"], "a": 0, "why": "HTTPS protects data in transit using secure mechanisms."}, {"t": "short", "q": "What is a protocol?", "keys": ["rule"], "hint": "Agreed rules that systems follow when communicating."}, {"t": "mcq", "q": "Which protocol is associated with sending email?", "o": ["SMTP", "FTP", "HTTP", "Ethernet only"], "a": 0, "why": "SMTP handles outgoing/sent email."}, {"t": "boss", "q": "A business hosts a website, sends email and lets staff synchronise inboxes across devices. Identify suitable protocols and explain the role of each."}]}, {"id": "tcp-ip", "title": "TCP/IP Four-Layer Model", "spec": "Topic 4", "learn": ["The TCP/IP model groups networking functions into layers.", "Application layer provides network services to applications.", "Transport layer manages end-to-end transport.", "Internet layer handles addressing/routing using IP.", "Link layer handles local network transmission technologies."], "example": "A web request begins with an application-layer protocol such as HTTPS; transport and internet layers prepare it for delivery; the link layer sends it over the local network.", "tasks": [{"t": "order", "q": "Put the TCP/IP layers from highest to lowest.", "items": [["Application", "a"], ["Transport", "b"], ["Internet", "c"], ["Link", "d"]], "a": ["a", "b", "c", "d"]}, {"t": "classify", "q": "Classify the example.", "cats": ["Application", "Transport", "Internet", "Link"], "items": [["HTTPS", 0], ["End-to-end delivery", 1], ["IP addressing/routing", 2], ["Ethernet/Wi-Fi local transmission", 3]]}, {"t": "mcq", "q": "Which layer is most directly associated with IP?", "o": ["Internet", "Application", "Link only", "None"], "a": 0, "why": "The Internet layer uses IP for addressing/routing."}, {"t": "short", "q": "Why is a layered model useful?", "keys": ["layer"], "hint": "Layers separate responsibilities and allow technologies/protocols to interact through defined roles."}, {"t": "boss", "q": "Describe how a secure webpage request moves down the TCP/IP layers before transmission and then back up the layers at the destination."}]}]}, {"id": "security-impact", "title": "Security & Impact", "icon": "🛡️", "colour": "pink", "desc": "Diagnose cyber threats, recommend protections and evaluate legal, ethical and societal impacts.", "subs": [{"id": "security-threats", "title": "Cyber Security Threats", "spec": "Topics 4/5", "learn": ["Security threats attempt to compromise confidentiality, integrity or availability.", "Threats include malware, unauthorised access, interception and denial-of-service attacks.", "Good answers link a threat to its likely impact rather than naming it only."], "example": "A denial-of-service attack floods a service with traffic or requests so legitimate users cannot access it.", "tasks": [{"t": "classify", "q": "Classify the threat.", "cats": ["Malware", "Brute force", "DoS", "Interception"], "items": [["Repeated password guesses", 1], ["Flooding a server with requests", 2], ["Malicious executable infects files", 0], ["Capturing data in transit", 3]]}, {"t": "mcq", "q": "Which security property is most directly affected by a successful DoS attack?", "o": ["Availability", "Colour depth", "Storage type", "Clock speed"], "a": 0, "why": "DoS attacks aim to make a service unavailable."}, {"t": "short", "q": "Why can intercepted unencrypted data be dangerous?", "keys": ["read"], "hint": "An attacker may read sensitive information."}, {"t": "mcq", "q": "Which threat involves malicious software?", "o": ["Malware", "Bandwidth", "Compression", "Cache"], "a": 0, "why": "Malware is malicious software."}, {"t": "boss", "q": "An online shop becomes unavailable during a sale and logs show huge numbers of automated requests. Diagnose the likely attack and explain two appropriate responses."}]}, {"id": "social-malware", "title": "Social Engineering & Malware", "spec": "Topics 4/5", "learn": ["Social engineering manipulates people rather than directly attacking technology.", "Phishing messages try to trick users into revealing information or opening malicious content.", "Malware types can steal, damage, encrypt or spy on data.", "User awareness is an important layer of defence."], "example": "A fake Microsoft 365 login email that links to a lookalike website is a phishing/social-engineering attack.", "tasks": [{"t": "mcq", "q": "Which is an example of phishing?", "o": ["A fake bank email asking you to sign in via a link", "A CPU adding numbers", "A file being compressed", "A monitor sleeping"], "a": 0, "why": "Phishing impersonates a trusted source to manipulate the victim."}, {"t": "classify", "q": "Classify the sign.", "cats": ["Suspicious", "Not automatically suspicious"], "items": [["Urgent threat to close account", 0], ["Unexpected attachment", 0], ["Correct internal email sent after a planned meeting", 1], ["Misspelled domain name", 0]]}, {"t": "short", "q": "Why can technical security controls alone fail against social engineering?", "keys": ["person"], "hint": "Attackers exploit human trust/decisions."}, {"t": "mcq", "q": "What is malware?", "o": ["Software designed to cause harm or unauthorised activity", "A type of monitor", "A network cable", "Any old software"], "a": 0, "why": "Malware is deliberately malicious software."}, {"t": "boss", "q": "Create a short staff-security briefing explaining how to spot a phishing attempt and what to do before clicking a link or opening an attachment."}]}, {"id": "security-controls", "title": "Firewalls, Anti-malware & Updates", "spec": "Topics 4/5", "learn": ["Firewalls control network traffic according to rules.", "Anti-malware software detects or blocks malicious software.", "Software updates can patch known vulnerabilities.", "Security works best in layers rather than relying on one control."], "example": "A firewall might block unwanted inbound traffic while anti-malware scans downloaded files and updates fix vulnerabilities.", "tasks": [{"t": "classify", "q": "Choose the control.", "cats": ["Firewall", "Anti-malware", "Software update"], "items": [["Filters network traffic", 0], ["Scans for malicious software", 1], ["Patches a vulnerability", 2]]}, {"t": "mcq", "q": "Why are security updates important?", "o": ["They can fix known vulnerabilities", "They always increase storage capacity", "They remove all passwords", "They replace backups"], "a": 0, "why": "Attackers often exploit known vulnerabilities that patches address."}, {"t": "short", "q": "Why is one security control rarely enough?", "keys": ["layer"], "hint": "Different controls protect against different attack routes."}, {"t": "mcq", "q": "Which control is most directly designed to inspect/block network connections?", "o": ["Firewall", "Spreadsheet", "SSD", "Compiler"], "a": 0, "why": "That is the role of a firewall."}, {"t": "boss", "q": "A school laptop fleet uses anti-malware but has not installed updates for months. Explain why the devices can still be vulnerable and recommend a layered response."}]}, {"id": "auth-encryption", "title": "Authentication, Access & Encryption", "spec": "Topics 4/5", "learn": ["Authentication checks that a user is who they claim to be.", "Strong authentication can combine passwords with another factor.", "Access levels limit what authenticated users are allowed to do.", "Encryption transforms data so it is unreadable without the appropriate key."], "example": "A teacher and student may both authenticate to the same system but have different access permissions.", "tasks": [{"t": "mcq", "q": "What is authentication?", "o": ["Checking identity", "Compressing a file", "Increasing bandwidth", "Sorting data"], "a": 0, "why": "Authentication verifies identity."}, {"t": "classify", "q": "Classify the measure.", "cats": ["Authentication", "Authorisation/access", "Encryption"], "items": [["Password plus code", 0], ["Student cannot edit staff records", 1], ["Unreadable ciphertext without key", 2]]}, {"t": "short", "q": "Why does encryption protect intercepted data?", "keys": ["key"], "hint": "Without the correct key, the captured data should be unreadable."}, {"t": "mcq", "q": "Why are access levels useful?", "o": ["Users receive only permissions needed for their role", "They make every user an administrator", "They eliminate authentication", "They increase clock speed"], "a": 0, "why": "Least privilege reduces damage and unauthorised access."}, {"t": "boss", "q": "Design security for an online school-report system. Include authentication, access levels and encryption, and explain what each control protects."}]}, {"id": "backup-recovery", "title": "Backups & Resilience", "spec": "Topics 4/5", "learn": ["Backups provide copies of important data that can be restored after loss or damage.", "A backup should be separate enough that the same incident does not destroy both original and copy.", "Recovery planning considers how quickly systems/data need to be restored.", "Backups complement security controls but do not stop every attack."], "example": "A ransomware incident may encrypt live files; a protected backup can allow data to be restored without relying on the damaged copy.", "tasks": [{"t": "mcq", "q": "What is the main purpose of a backup?", "o": ["Allow data restoration after loss/damage", "Increase CPU speed", "Replace authentication", "Reduce image resolution"], "a": 0, "why": "Backups provide recoverable copies."}, {"t": "mcq", "q": "Why should backups not all be permanently connected to the live system?", "o": ["Some attacks could damage/encrypt both live data and connected backups", "Connected storage is always slower", "Backups cannot use networks", "It changes IP addresses"], "a": 0, "why": "Separation reduces correlated failure."}, {"t": "short", "q": "Why does having a backup not prevent malware infection?", "keys": ["restore"], "hint": "A backup helps recovery; it is not itself a malware-prevention control."}, {"t": "classify", "q": "Classify the action.", "cats": ["Prevention", "Recovery"], "items": [["Patch software", 0], ["Restore files from backup", 1], ["Use firewall rules", 0], ["Rebuild data from backup", 1]]}, {"t": "boss", "q": "A small business loses its main server in a hardware failure. Explain what a good backup and recovery plan should have included before the failure."}]}, {"id": "legal-ethical", "title": "Legal, Ethical & Environmental Issues", "spec": "Topic 5", "learn": ["Computer use raises legal, ethical, privacy and environmental issues.", "Copyright protects creators' work and affects how digital content can be copied or reused.", "Organisations have responsibilities when handling personal data.", "Technology has environmental costs through energy use, manufacturing and electronic waste."], "example": "Using a copyrighted image from the internet in a commercial product without permission may breach the creator's rights even though the file is easy to copy.", "tasks": [{"t": "classify", "q": "Classify the issue.", "cats": ["Legal/rights", "Privacy", "Environmental"], "items": [["Copying software without permission", 0], ["Collecting unnecessary personal data", 1], ["Discarded electronic devices", 2], ["Using someone's photo without appropriate permission", 0]]}, {"t": "mcq", "q": "Which is an environmental concern linked to computing?", "o": ["Electronic waste", "Boolean logic", "Binary search", "Variable naming"], "a": 0, "why": "Manufacture, energy consumption and e-waste have environmental impacts."}, {"t": "short", "q": "Why can collecting more personal data than necessary create an ethical/privacy concern?", "keys": ["privacy"], "hint": "More data increases intrusion and potential harm if misused or breached."}, {"t": "mcq", "q": "Copyright mainly protects what?", "o": ["Creative works and the rights of their creators", "CPU registers", "IP routing tables", "RAM volatility"], "a": 0, "why": "Copyright concerns ownership and permitted use of creative work."}, {"t": "boss", "q": "A company wants to use facial recognition to monitor staff attendance. Evaluate the idea from privacy, security, fairness and efficiency perspectives."}]}, {"id": "ai-automation", "title": "AI, Automation & Robotics", "spec": "Topic 5", "learn": ["AI systems can perform tasks that appear to require intelligent decision-making.", "Machine-learning systems learn patterns from data rather than relying only on fixed hand-written rules.", "Automation and robotics can improve speed, consistency and safety but can also change jobs and introduce new risks.", "Evaluations should consider benefits, limitations, bias, accountability and human oversight."], "example": "A warehouse robot can move stock consistently and work in hazardous areas, but the organisation must consider safety, maintenance, job changes and what happens when the system makes an error.", "tasks": [{"t": "classify", "q": "Classify the consideration.", "cats": ["Benefit", "Risk/concern"], "items": [["Can perform repetitive work consistently", 0], ["Training data may contain bias", 1], ["Can operate in dangerous environments", 0], ["Responsibility for wrong decisions may be unclear", 1]]}, {"t": "mcq", "q": "What is a key difference between machine learning and a simple fixed-rule program?", "o": ["Machine learning finds patterns from training data", "It never uses data", "It cannot make predictions", "It only works offline"], "a": 0, "why": "Machine learning derives behaviour/patterns from data."}, {"t": "short", "q": "Why is human oversight important in some AI systems?", "keys": ["decision"], "hint": "Humans may need to review high-impact decisions, errors or unusual cases."}, {"t": "mcq", "q": "Which is a possible workplace impact of automation?", "o": ["Some tasks/jobs change or disappear while new roles may be created", "All work ends immediately", "Networks become unnecessary", "Copyright disappears"], "a": 0, "why": "Automation changes task demand rather than having one universal effect."}, {"t": "boss", "q": "A hospital is considering an AI system to prioritise patients for appointments. Evaluate potential benefits and risks, including data quality, bias, privacy and human oversight."}]}]}];
